$chapters = @"

,  {"id":"SAT-10-02-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Solve for x: 3x + 7 = 22","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x = 5"},{"id":"b","text":"x = 3"},{"id":"c","text":"x = 7"},{"id":"d","text":"x = 9"}],"correctOptionId":"a","explanation":"3x + 7 = 22 -> 3x = 15 -> x = 5.","difficulty":"Easy"},
  {"id":"SAT-10-02-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"What is the slope of y = -2x + 5?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"-2"},{"id":"b","text":"2"},{"id":"c","text":"5"},{"id":"d","text":"-5"}],"correctOptionId":"a","explanation":"In y = mx + b, m is the slope. Here m = -2.","difficulty":"Easy"},
  {"id":"SAT-10-02-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"If f(x) = 2x - 3, what is f(4)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5"},{"id":"b","text":"11"},{"id":"c","text":"8"},{"id":"d","text":"6"}],"correctOptionId":"a","explanation":"f(4) = 2(4) - 3 = 8 - 3 = 5.","difficulty":"Easy"},
  {"id":"SAT-10-02-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"What is the y-intercept of 3x + 2y = 12?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"6"},{"id":"b","text":"4"},{"id":"c","text":"3"},{"id":"d","text":"12"}],"correctOptionId":"a","explanation":"Set x = 0: 2y = 12, y = 6.","difficulty":"Easy"},
  {"id":"SAT-10-02-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Simplify: 4(x + 3) - 2(x - 1)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"2x + 14"},{"id":"b","text":"2x + 10"},{"id":"c","text":"6x + 10"},{"id":"d","text":"2x + 2"}],"correctOptionId":"a","explanation":"4x + 12 - 2x + 2 = 2x + 14.","difficulty":"Easy"},
  {"id":"SAT-10-02-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"If g(x) = x^2 - 4, what is g(3)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5"},{"id":"b","text":"9"},{"id":"c","text":"13"},{"id":"d","text":"0"}],"correctOptionId":"a","explanation":"g(3) = 3^2 - 4 = 9 - 4 = 5.","difficulty":"Easy"},
  {"id":"SAT-10-02-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Solve: x + y = 10, x - y = 4","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x = 7, y = 3"},{"id":"b","text":"x = 6, y = 4"},{"id":"c","text":"x = 5, y = 5"},{"id":"d","text":"x = 8, y = 2"}],"correctOptionId":"a","explanation":"Adding: 2x = 14, x = 7. Then y = 3.","difficulty":"Easy"},
  {"id":"SAT-10-02-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Which is parallel to y = 3x + 1?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"y = 3x - 5"},{"id":"b","text":"y = -3x + 1"},{"id":"c","text":"y = x + 3"},{"id":"d","text":"y = 3x^2 + 1"}],"correctOptionId":"a","explanation":"Parallel lines have the same slope. y = 3x - 5 has slope 3.","difficulty":"Easy"},
  {"id":"SAT-10-02-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Solve: 5x - 3 = 2x + 12","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"3"},{"id":"b","text":"5"},{"id":"c","text":"7"},{"id":"d","text":"9"}],"correctOptionId":"b","explanation":"5x - 3 = 2x + 12 -> 3x = 15 -> x = 5.","difficulty":"Easy"},
  {"id":"SAT-10-02-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"If f(x) = x + 7 and g(x) = 2x, what is f(g(3))?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"13"},{"id":"b","text":"27"},{"id":"c","text":"10"},{"id":"d","text":"20"}],"correctOptionId":"a","explanation":"g(3) = 6, f(6) = 6 + 7 = 13.","difficulty":"Easy"},
  {"id":"SAT-10-02-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Solve: |2x - 5| = 9","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x = 7 or x = -2"},{"id":"b","text":"x = 7 or x = 2"},{"id":"c","text":"x = -7 or x = 2"},{"id":"d","text":"x = 7 only"}],"correctOptionId":"a","explanation":"2x - 5 = 9 -> x = 7, or 2x - 5 = -9 -> x = -2.","difficulty":"Medium"},
  {"id":"SAT-10-02-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"What is the vertex of y = x^2 - 6x + 8?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"(3, -1)"},{"id":"b","text":"(3, 1)"},{"id":"c","text":"(-3, -1)"},{"id":"d","text":"(6, 8)"}],"correctOptionId":"a","explanation":"x = -(-6)/(2*1) = 3. y = 9 - 18 + 8 = -1. Vertex: (3, -1).","difficulty":"Medium"},
  {"id":"SAT-10-02-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"If f(x) = 3x + 2, what is f^-1(x)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"(x - 2)/3"},{"id":"b","text":"(x + 2)/3"},{"id":"c","text":"3x - 2"},{"id":"d","text":"(x - 2)/3"}],"correctOptionId":"a","explanation":"Set y = 3x + 2, solve: x = (y - 2)/3, so f^-1(x) = (x - 2)/3.","difficulty":"Medium"},
  {"id":"SAT-10-02-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"What are the zeros of f(x) = x^2 - 5x + 6?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x = 2 and x = 3"},{"id":"b","text":"x = -2 and x = -3"},{"id":"c","text":"x = 1 and x = 6"},{"id":"d","text":"x = -1 and x = 6"}],"correctOptionId":"a","explanation":"x^2 - 5x + 6 = (x - 2)(x - 3) = 0, so x = 2 or x = 3.","difficulty":"Medium"},
  {"id":"SAT-10-02-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Line through (2,5) and (6,13). What is its equation?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"y = 2x + 1"},{"id":"b","text":"y = 2x - 1"},{"id":"c","text":"y = x + 3"},{"id":"d","text":"y = 3x - 1"}],"correctOptionId":"a","explanation":"Slope = (13-5)/(6-2) = 2. y - 5 = 2(x - 2) -> y = 2x + 1.","difficulty":"Medium"},
  {"id":"SAT-10-02-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Simplify: (x^2 - 9)/(x + 3)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x - 3"},{"id":"b","text":"x + 3"},{"id":"c","text":"x^2 - 3"},{"id":"d","text":"x + 9"}],"correctOptionId":"a","explanation":"x^2 - 9 = (x+3)(x-3), so (x^2-9)/(x+3) = x - 3.","difficulty":"Medium"},
  {"id":"SAT-10-02-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"What is the range of f(x) = x^2 + 2?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"y >= 0"},{"id":"b","text":"y >= 2"},{"id":"c","text":"y > 2"},{"id":"d","text":"All real numbers"}],"correctOptionId":"b","explanation":"x^2 >= 0, so x^2 + 2 >= 2. Range: y >= 2.","difficulty":"Medium"},
  {"id":"SAT-10-02-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"If f(x) = 2x - 1 and g(x) = x^2 + 3, what is (f + g)(x)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x^2 + 2x + 2"},{"id":"b","text":"x^2 + 2x + 4"},{"id":"c","text":"2x^3 - x^2 + 6x - 3"},{"id":"d","text":"x^2 + 2x - 2"}],"correctOptionId":"a","explanation":"(f + g)(x) = 2x - 1 + x^2 + 3 = x^2 + 2x + 2.","difficulty":"Medium"},
  {"id":"SAT-10-02-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"What is the domain of f(x) = sqrt(x - 4)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x >= 4"},{"id":"b","text":"x > 4"},{"id":"c","text":"x >= 0"},{"id":"d","text":"All real numbers"}],"correctOptionId":"a","explanation":"x - 4 >= 0, so x >= 4.","difficulty":"Medium"},
  {"id":"SAT-10-02-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Solve: x^2 - 4x - 5 = 0","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"x = 5 or x = -1"},{"id":"b","text":"x = -5 or x = 1"},{"id":"c","text":"x = 5 or x = 1"},{"id":"d","text":"x = -5 or x = -1"}],"correctOptionId":"a","explanation":"(x - 5)(x + 1) = 0, so x = 5 or x = -1.","difficulty":"Medium"},
  {"id":"SAT-10-02-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"If f(x) = x^2 - 2x + 1, how many values of x make f(x) = 0?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"2"},{"id":"d","text":"3"}],"correctOptionId":"b","explanation":"x^2 - 2x + 1 = (x - 1)^2 = 0, one repeated root at x = 1.","difficulty":"Hard"},
  {"id":"SAT-10-02-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Parabola with vertex (2,-3) through (0,1). What is a in y = a(x-2)^2 - 3?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"1"},{"id":"b","text":"2"},{"id":"c","text":"-1"},{"id":"d","text":"3"}],"correctOptionId":"a","explanation":"1 = a(0-2)^2 - 3 = 4a - 3, so a = 1.","difficulty":"Hard"},
  {"id":"SAT-10-02-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"For which k does x^2 + kx + 9 = 0 have two distinct real solutions?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"k > 6"},{"id":"b","text":"k > 6 or k < -6"},{"id":"c","text":"k != +-6"},{"id":"d","text":"-6 < k < 6"}],"correctOptionId":"b","explanation":"Discriminant > 0: k^2 - 36 > 0 -> k > 6 or k < -6.","difficulty":"Hard"},
  {"id":"SAT-10-02-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"For f(x) = (2x+1)/(x-3), what is the horizontal asymptote?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"y = 2"},{"id":"b","text":"y = 1/3"},{"id":"c","text":"y = 0"},{"id":"d","text":"x = 3"}],"correctOptionId":"a","explanation":"Equal degrees: horizontal asymptote = ratio of leading coefficients = 2/1 = 2.","difficulty":"Hard"},
  {"id":"SAT-10-02-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Remainder when x^3 - 2x^2 + 3x - 1 is divided by x - 1?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"1"},{"id":"b","text":"0"},{"id":"c","text":"-1"},{"id":"d","text":"3"}],"correctOptionId":"a","explanation":"By Remainder Theorem, f(1) = 1 - 2 + 3 - 1 = 1.","difficulty":"Hard"},
  {"id":"SAT-10-02-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"Graphs of f and g intersect at (3,5). What is h(3) if h(x) = f(x) - g(x)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5"},{"id":"b","text":"3"},{"id":"c","text":"0"},{"id":"d","text":"10"}],"correctOptionId":"c","explanation":"At intersection f(3) = g(3) = 5, so h(3) = 5 - 5 = 0.","difficulty":"Hard"},
  {"id":"SAT-10-02-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"If log2(x) + log2(x-2) = 3, what is x?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"4"},{"id":"b","text":"8"},{"id":"c","text":"-2"},{"id":"d","text":"2"}],"correctOptionId":"a","explanation":"log2(x(x-2)) = 3 -> x(x-2) = 8 -> x^2-2x-8 = 0 -> (x-4)(x+2) = 0. x = 4.","difficulty":"Hard"},
  {"id":"SAT-10-02-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"f(x+1) = 2f(x) for all x and f(0) = 3. What is f(3)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"6"},{"id":"b","text":"12"},{"id":"c","text":"24"},{"id":"d","text":"48"}],"correctOptionId":"c","explanation":"f(1) = 6, f(2) = 12, f(3) = 24.","difficulty":"Hard"},
  {"id":"SAT-10-02-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"What is the minimum value of f(x) = 2x^2 - 8x + 5?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"-3"},{"id":"b","text":"5"},{"id":"c","text":"3"},{"id":"d","text":"-5"}],"correctOptionId":"a","explanation":"Vertex x = 8/4 = 2. f(2) = 8 - 16 + 5 = -3.","difficulty":"Hard"},
  {"id":"SAT-10-02-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 2: Algebra and Functions","yearEC":"2024 E.C.","questionText":"If f(x) = |x - 3| + 2, how many values of x make f(x) = 5?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"2"},{"id":"d","text":"3"}],"correctOptionId":"c","explanation":"|x-3| + 2 = 5 -> |x-3| = 3 -> x = 6 or x = 0. Two values.","difficulty":"Hard"},
  {"id":"SAT-10-03-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Area of a rectangle with length 12 cm and width 5 cm?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"60 cm^2"},{"id":"b","text":"34 cm^2"},{"id":"c","text":"17 cm^2"},{"id":"d","text":"120 cm^2"}],"correctOptionId":"a","explanation":"Area = 12 x 5 = 60 cm^2.","difficulty":"Easy"},
  {"id":"SAT-10-03-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Circumference of a circle with radius 7 cm? (pi = 22/7)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"44 cm"},{"id":"b","text":"22 cm"},{"id":"c","text":"154 cm"},{"id":"d","text":"88 cm"}],"correctOptionId":"a","explanation":"C = 2pi*r = 2 x (22/7) x 7 = 44 cm.","difficulty":"Easy"},
  {"id":"SAT-10-03-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Perimeter of an equilateral triangle with side 9 m?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"27 m"},{"id":"b","text":"18 m"},{"id":"c","text":"36 m"},{"id":"d","text":"9 m"}],"correctOptionId":"a","explanation":"Perimeter = 3 x 9 = 27 m.","difficulty":"Easy"},
  {"id":"SAT-10-03-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Area of a triangle with base 10 cm and height 6 cm?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"30 cm^2"},{"id":"b","text":"60 cm^2"},{"id":"c","text":"16 cm^2"},{"id":"d","text":"15 cm^2"}],"correctOptionId":"a","explanation":"Area = (1/2) x 10 x 6 = 30 cm^2.","difficulty":"Easy"},
  {"id":"SAT-10-03-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Volume of a cube with side 4 cm?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"16 cm^3"},{"id":"b","text":"64 cm^3"},{"id":"c","text":"48 cm^3"},{"id":"d","text":"24 cm^3"}],"correctOptionId":"b","explanation":"Volume = 4^3 = 64 cm^3.","difficulty":"Easy"},
  {"id":"SAT-10-03-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Sum of interior angles of a hexagon?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"540"},{"id":"b","text":"720"},{"id":"c","text":"360"},{"id":"d","text":"1080"}],"correctOptionId":"b","explanation":"Sum = (6-2) x 180 = 720 degrees.","difficulty":"Easy"},
  {"id":"SAT-10-03-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Right triangle legs 3 and 4. Hypotenuse length?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5"},{"id":"b","text":"7"},{"id":"c","text":"6"},{"id":"d","text":"25"}],"correctOptionId":"a","explanation":"c^2 = 3^2 + 4^2 = 9 + 16 = 25, c = 5.","difficulty":"Easy"},
  {"id":"SAT-10-03-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Area of a circle with diameter 10 cm? (pi = 3.14)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"31.4 cm^2"},{"id":"b","text":"78.5 cm^2"},{"id":"c","text":"153.86 cm^2"},{"id":"d","text":"314 cm^2"}],"correctOptionId":"b","explanation":"r = 5. Area = 3.14 x 25 = 78.5 cm^2.","difficulty":"Easy"},
  {"id":"SAT-10-03-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Diagonal of a square with side 5 cm?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"10 cm"},{"id":"b","text":"5sqrt(2) cm"},{"id":"c","text":"25 cm"},{"id":"d","text":"5 cm"}],"correctOptionId":"b","explanation":"Diagonal = s*sqrt(2) = 5sqrt(2) cm.","difficulty":"Easy"},
  {"id":"SAT-10-03-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Volume of rectangular prism: 3m x 4m x 5m?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"12 m^3"},{"id":"b","text":"60 m^3"},{"id":"c","text":"47 m^3"},{"id":"d","text":"20 m^3"}],"correctOptionId":"b","explanation":"Volume = 3 x 4 x 5 = 60 m^3.","difficulty":"Easy"},
  {"id":"SAT-10-03-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Similar triangles with ratio 2:3. Smaller area = 12 cm^2. Larger area?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"18 cm^2"},{"id":"b","text":"27 cm^2"},{"id":"c","text":"24 cm^2"},{"id":"d","text":"36 cm^2"}],"correctOptionId":"b","explanation":"Area ratio = 4:9. 12 x (9/4) = 27 cm^2.","difficulty":"Medium"},
  {"id":"SAT-10-03-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Surface area of cylinder r=3cm, h=7cm? (pi = 22/7)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"198 cm^2"},{"id":"b","text":"132 cm^2"},{"id":"c","text":"66 cm^2"},{"id":"d","text":"264 cm^2"}],"correctOptionId":"a","explanation":"SA = 2pi*r^2 + 2pi*r*h = 2(22/7)(9) + 2(22/7)(3)(7) = 198 cm^2.","difficulty":"Medium"},
  {"id":"SAT-10-03-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Central angle 60 degrees. Inscribed angle on same arc?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"60"},{"id":"b","text":"30"},{"id":"c","text":"120"},{"id":"d","text":"45"}],"correctOptionId":"b","explanation":"Inscribed angle = half of central angle = 60/2 = 30 degrees.","difficulty":"Medium"},
  {"id":"SAT-10-03-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Area of trapezoid with bases 8 and 12, height 5?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"50 cm^2"},{"id":"b","text":"100 cm^2"},{"id":"c","text":"25 cm^2"},{"id":"d","text":"40 cm^2"}],"correctOptionId":"a","explanation":"Area = (1/2)(8+12)(5) = 50 cm^2.","difficulty":"Medium"},
  {"id":"SAT-10-03-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Volume of cone r=6cm, h=8cm? (pi=3.14)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"301.44 cm^3"},{"id":"b","text":"904.32 cm^3"},{"id":"c","text":"150.72 cm^3"},{"id":"d","text":"602.88 cm^3"}],"correctOptionId":"a","explanation":"V = (1/3)pi*r^2*h = (1/3)(3.14)(36)(8) = 301.44 cm^3.","difficulty":"Medium"},
  {"id":"SAT-10-03-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Arc length for 90 degree angle, radius 8 cm?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"4pi cm"},{"id":"b","text":"8pi cm"},{"id":"c","text":"16pi cm"},{"id":"d","text":"2pi cm"}],"correctOptionId":"a","explanation":"Arc = (90/360) x 2pi(8) = (1/4) x 16pi = 4pi cm.","difficulty":"Medium"},
  {"id":"SAT-10-03-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Right triangle, one acute angle 35 degrees. Other acute angle?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"55"},{"id":"b","text":"65"},{"id":"c","text":"45"},{"id":"d","text":"35"}],"correctOptionId":"a","explanation":"90 - 35 = 55 degrees.","difficulty":"Medium"},
  {"id":"SAT-10-03-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Cylinder circumference 20pi cm. Radius?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"10 cm"},{"id":"b","text":"20 cm"},{"id":"c","text":"5 cm"},{"id":"d","text":"40 cm"}],"correctOptionId":"a","explanation":"2pi*r = 20pi -> r = 10 cm.","difficulty":"Medium"},
  {"id":"SAT-10-03-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Area of regular hexagon with side 6 cm?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"54sqrt(3) cm^2"},{"id":"b","text":"36sqrt(3) cm^2"},{"id":"c","text":"108 cm^2"},{"id":"d","text":"72sqrt(3) cm^2"}],"correctOptionId":"a","explanation":"Area = (3sqrt(3)/2)s^2 = (3sqrt(3)/2)(36) = 54sqrt(3) cm^2.","difficulty":"Medium"},
  {"id":"SAT-10-03-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Volume of sphere with radius 3 cm? (pi=3.14)","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"113.04 cm^3"},{"id":"b","text":"36pi cm^3"},{"id":"c","text":"339.12 cm^3"},{"id":"d","text":"28.26 cm^3"}],"correctOptionId":"a","explanation":"V = (4/3)pi*r^3 = (4/3)(3.14)(27) = 113.04 cm^3.","difficulty":"Medium"},
  {"id":"SAT-10-03-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Chord 3cm from center, radius 5cm. Chord length?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"6 cm"},{"id":"b","text":"8 cm"},{"id":"c","text":"10 cm"},{"id":"d","text":"4 cm"}],"correctOptionId":"b","explanation":"Half-chord = sqrt(25-9) = 4. Chord = 8 cm.","difficulty":"Hard"},
  {"id":"SAT-10-03-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Pyramid square base 4cm, slant height 5cm. Lateral surface area?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"40 cm^2"},{"id":"b","text":"16 cm^2"},{"id":"c","text":"20 cm^2"},{"id":"d","text":"80 cm^2"}],"correctOptionId":"a","explanation":"Lateral SA = 4 x (1/2) x 4 x 5 = 40 cm^2.","difficulty":"Hard"},
  {"id":"SAT-10-03-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Parallel lines, consecutive interior angle 65 degrees. Other angle?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"65"},{"id":"b","text":"115"},{"id":"c","text":"25"},{"id":"d","text":"125"}],"correctOptionId":"b","explanation":"Consecutive interior angles supplementary: 180 - 65 = 115 degrees.","difficulty":"Hard"},
  {"id":"SAT-10-03-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Square inscribed in circle radius 5cm. Area of square?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"50 cm^2"},{"id":"b","text":"25 cm^2"},{"id":"c","text":"100 cm^2"},{"id":"d","text":"20 cm^2"}],"correctOptionId":"a","explanation":"Diagonal = 10, side = 10/sqrt(2) = 5sqrt(2), area = 50 cm^2.","difficulty":"Hard"},
  {"id":"SAT-10-03-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Sector area 20pi, central angle 40 degrees. Radius?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"sqrt(180) cm"},{"id":"b","text":"12 cm"},{"id":"c","text":"15 cm"},{"id":"d","text":"6sqrt(5) cm"}],"correctOptionId":"d","explanation":"20pi = (40/360)pi*r^2 -> r^2 = 180 -> r = sqrt(180) = 6sqrt(5) cm.","difficulty":"Hard"},
  {"id":"SAT-10-03-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Distance between (1,2) and (4,6)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5"},{"id":"b","text":"7"},{"id":"c","text":"25"},{"id":"d","text":"3"}],"correctOptionId":"a","explanation":"d = sqrt((4-1)^2 + (6-2)^2) = sqrt(9+16) = sqrt(25) = 5.","difficulty":"Hard"},
  {"id":"SAT-10-03-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Sphere surface area 100pi. Volume?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"(500/3)pi cm^3"},{"id":"b","text":"250pi cm^3"},{"id":"c","text":"125pi cm^3"},{"id":"d","text":"(250/3)pi cm^3"}],"correctOptionId":"a","explanation":"4pi*r^2 = 100pi -> r = 5. V = (4/3)pi(125) = (500/3)pi.","difficulty":"Hard"},
  {"id":"SAT-10-03-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Triangle vertices A(0,0), B(6,0), C(3,4). Area?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"12"},{"id":"b","text":"24"},{"id":"c","text":"6"},{"id":"d","text":"10"}],"correctOptionId":"a","explanation":"Area = (1/2)|0(0-4) + 6(4-0) + 3(0-0)| = (1/2)(24) = 12.","difficulty":"Hard"},
  {"id":"SAT-10-03-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Regular polygon interior angle 156 degrees. Number of sides?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"12"},{"id":"b","text":"15"},{"id":"c","text":"24"},{"id":"d","text":"18"}],"correctOptionId":"b","explanation":"(n-2)*180/n = 156 -> 180n - 360 = 156n -> 24n = 360 -> n = 15.","difficulty":"Hard"},
  {"id":"SAT-10-03-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 3: Geometry and Measurement","yearEC":"2024 E.C.","questionText":"Cylinder inscribed in sphere radius R, height 2R/sqrt(3). Volume?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"(2pi*R^3)/sqrt(3)"},{"id":"b","text":"(4pi*R^3)/3"},{"id":"c","text":"pi*R^3"},{"id":"d","text":"(2pi*R^3)/3"}],"correctOptionId":"a","explanation":"r^2 = R^2 - R^2/3 = 2R^2/3. V = pi(2R^2/3)(2R/sqrt(3)) = (4pi*R^3)/(3sqrt(3)) = (2pi*R^3)/sqrt(3).","difficulty":"Hard"},
  {"id":"SAT-10-04-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Mean of: 4, 8, 6, 10, 2?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"6"},{"id":"b","text":"8"},{"id":"c","text":"5"},{"id":"d","text":"7"}],"correctOptionId":"a","explanation":"Mean = (4+8+6+10+2)/5 = 30/5 = 6.","difficulty":"Easy"},
  {"id":"SAT-10-04-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Median of: 3, 7, 1, 9, 5?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5"},{"id":"b","text":"7"},{"id":"c","text":"3"},{"id":"d","text":"9"}],"correctOptionId":"a","explanation":"Ordered: 1, 3, 5, 7, 9. Median = 5.","difficulty":"Easy"},
  {"id":"SAT-10-04-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Coin flipped twice. P(two heads)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"1/4"},{"id":"b","text":"1/2"},{"id":"c","text":"1/3"},{"id":"d","text":"3/4"}],"correctOptionId":"a","explanation":"P(HH) = 1/2 x 1/2 = 1/4.","difficulty":"Easy"},
  {"id":"SAT-10-04-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Mode of: 2, 3, 5, 3, 7, 3, 9?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"3"},{"id":"b","text":"5"},{"id":"c","text":"7"},{"id":"d","text":"2"}],"correctOptionId":"a","explanation":"3 appears most frequently (3 times).","difficulty":"Easy"},
  {"id":"SAT-10-04-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Range of: 12, 5, 18, 3, 9?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"15"},{"id":"b","text":"9"},{"id":"c","text":"18"},{"id":"d","text":"5"}],"correctOptionId":"a","explanation":"Range = 18 - 3 = 15.","difficulty":"Easy"},
  {"id":"SAT-10-04-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Bag: 4 red, 6 blue marbles. P(red)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"2/5"},{"id":"b","text":"3/5"},{"id":"c","text":"2/3"},{"id":"d","text":"4/6"}],"correctOptionId":"a","explanation":"P(red) = 4/10 = 2/5.","difficulty":"Easy"},
  {"id":"SAT-10-04-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Die rolled once. P(number > 4)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"1/3"},{"id":"b","text":"1/2"},{"id":"c","text":"1/6"},{"id":"d","text":"2/3"}],"correctOptionId":"a","explanation":"Numbers > 4: 5, 6. P = 2/6 = 1/3.","difficulty":"Easy"},
  {"id":"SAT-10-04-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Stem-and-leaf: 1|2,5  2|3,7,8  3|1. Median?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"23"},{"id":"b","text":"25"},{"id":"c","text":"27"},{"id":"d","text":"23.5"}],"correctOptionId":"b","explanation":"Data: 12, 15, 23, 27, 28, 31. Median = (23+27)/2 = 25.","difficulty":"Easy"},
  {"id":"SAT-10-04-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"P(choosing a vowel from English alphabet)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5/26"},{"id":"b","text":"21/26"},{"id":"c","text":"1/5"},{"id":"d","text":"2/13"}],"correctOptionId":"a","explanation":"5 vowels out of 26 letters. P = 5/26.","difficulty":"Easy"},
  {"id":"SAT-10-04-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Box plot: Q1=20, Q2=35, Q3=50. IQR?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"30"},{"id":"b","text":"15"},{"id":"c","text":"25"},{"id":"d","text":"35"}],"correctOptionId":"a","explanation":"IQR = Q3 - Q1 = 50 - 20 = 30.","difficulty":"Easy"},
  {"id":"SAT-10-04-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Two dice rolled. P(sum = 7)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"1/6"},{"id":"b","text":"1/12"},{"id":"c","text":"7/36"},{"id":"d","text":"1/9"}],"correctOptionId":"a","explanation":"6 ways to get 7 out of 36: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1). P = 6/36 = 1/6.","difficulty":"Medium"},
  {"id":"SAT-10-04-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Mean of 5 numbers is 18. Remove one, mean = 16. Removed number?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"26"},{"id":"b","text":"24"},{"id":"c","text":"28"},{"id":"d","text":"22"}],"correctOptionId":"a","explanation":"Sum of 5 = 90. Sum of 4 = 64. Removed = 90 - 64 = 26.","difficulty":"Medium"},
  {"id":"SAT-10-04-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Card drawn. P(king or heart)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"4/13"},{"id":"b","text":"1/13"},{"id":"c","text":"17/52"},{"id":"d","text":"1/52"}],"correctOptionId":"a","explanation":"P(K or H) = 4/52 + 13/52 - 1/52 = 16/52 = 4/13.","difficulty":"Medium"},
  {"id":"SAT-10-04-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Variance = 16. Standard deviation?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"8"},{"id":"b","text":"4"},{"id":"c","text":"256"},{"id":"d","text":"2"}],"correctOptionId":"b","explanation":"SD = sqrt(variance) = sqrt(16) = 4.","difficulty":"Medium"},
  {"id":"SAT-10-04-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"30 students: 18 soccer, 12 basketball, 5 both. Neither?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"5"},{"id":"b","text":"7"},{"id":"c","text":"3"},{"id":"d","text":"10"}],"correctOptionId":"a","explanation":"S union B = 18+12-5 = 25. Neither = 30-25 = 5.","difficulty":"Medium"},
  {"id":"SAT-10-04-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Box plot: Q1=55, Q2=70, Q3=85. Percent above 85?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"25%"},{"id":"b","text":"50%"},{"id":"c","text":"75%"},{"id":"d","text":"10%"}],"correctOptionId":"a","explanation":"Q3 = 75th percentile, so 25% above.","difficulty":"Medium"},
  {"id":"SAT-10-04-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"P(A)=0.3, P(B)=0.5, independent. P(A and B)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"0.15"},{"id":"b","text":"0.8"},{"id":"c","text":"0.6"},{"id":"d","text":"0.25"}],"correctOptionId":"a","explanation":"P(A and B) = 0.3 x 0.5 = 0.15.","difficulty":"Medium"},
  {"id":"SAT-10-04-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"40% of 500 students prefer chocolate. How many?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"200"},{"id":"b","text":"100"},{"id":"c","text":"250"},{"id":"d","text":"300"}],"correctOptionId":"a","explanation":"40% of 500 = 200.","difficulty":"Medium"},
  {"id":"SAT-10-04-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Mean of 3 numbers is 20. Two are 15 and 25. Third?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"20"},{"id":"b","text":"25"},{"id":"c","text":"15"},{"id":"d","text":"30"}],"correctOptionId":"a","explanation":"Sum = 60. Third = 60 - 15 - 25 = 20.","difficulty":"Medium"},
  {"id":"SAT-10-04-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Line of best fit y = 2x + 3. Predicted y when x = 7?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"17"},{"id":"b","text":"14"},{"id":"c","text":"10"},{"id":"d","text":"21"}],"correctOptionId":"a","explanation":"y = 2(7) + 3 = 17.","difficulty":"Medium"},
  {"id":"SAT-10-04-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Normal distribution mean 50, SD 5. Percent between 45 and 55?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"68%"},{"id":"b","text":"95%"},{"id":"c","text":"99.7%"},{"id":"d","text":"50%"}],"correctOptionId":"a","explanation":"Within 1 SD of mean: approximately 68%.","difficulty":"Hard"},
  {"id":"SAT-10-04-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Committee of 3 from 5 men, 4 women. P(at least 1 woman)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"37/42"},{"id":"b","text":"5/42"},{"id":"c","text":"1/6"},{"id":"d","text":"20/42"}],"correctOptionId":"a","explanation":"P(at least 1W) = 1 - C(5,3)/C(9,3) = 1 - 10/84 = 74/84 = 37/42.","difficulty":"Hard"},
  {"id":"SAT-10-04-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Data set {3, 5, 5, 7}. Standard deviation?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"sqrt(2)"},{"id":"b","text":"sqrt(5/2)"},{"id":"c","text":"2"},{"id":"d","text":"sqrt(5)"}],"correctOptionId":"a","explanation":"Mean = 5. Variance = (4+0+0+4)/4 = 2. SD = sqrt(2).","difficulty":"Hard"},
  {"id":"SAT-10-04-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Correlation coefficient -0.8. Best description?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"Strong negative"},{"id":"b","text":"Strong positive"},{"id":"c","text":"Weak negative"},{"id":"d","text":"No correlation"}],"correctOptionId":"a","explanation":"-0.8 indicates strong negative linear relationship.","difficulty":"Hard"},
  {"id":"SAT-10-04-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Jar: 3 red, 5 blue, 2 green. Two drawn without replacement. P(both red)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"1/15"},{"id":"b","text":"3/50"},{"id":"c","text":"3/10"},{"id":"d","text":"9/100"}],"correctOptionId":"a","explanation":"P = (3/10)(2/9) = 6/90 = 1/15.","difficulty":"Hard"},
  {"id":"SAT-10-04-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Median of 9 numbers is 15. All doubled. New median?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"15"},{"id":"b","text":"30"},{"id":"c","text":"7.5"},{"id":"d","text":"22.5"}],"correctOptionId":"b","explanation":"Doubling all values doubles the median: 15 x 2 = 30.","difficulty":"Hard"},
  {"id":"SAT-10-04-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Biased coin P(H)=0.6. Flipped 5 times. P(exactly 3 heads)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"C(5,3)(0.6)^3(0.4)^2"},{"id":"b","text":"(0.6)^3"},{"id":"c","text":"C(5,3)(0.6)^2(0.4)^3"},{"id":"d","text":"5(0.6)(0.4)^4"}],"correctOptionId":"a","explanation":"Binomial: P(X=3) = C(5,3)(0.6)^3(0.4)^2.","difficulty":"Hard"},
  {"id":"SAT-10-04-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Histogram: 25 students scored 80-89 out of 100. Relative frequency?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"0.25"},{"id":"b","text":"0.15"},{"id":"c","text":"0.40"},{"id":"d","text":"0.50"}],"correctOptionId":"a","explanation":"Relative frequency = 25/100 = 0.25.","difficulty":"Hard"},
  {"id":"SAT-10-04-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Mutually exclusive: P(A)=0.35, P(B)=0.25. P(A or B)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"0.60"},{"id":"b","text":"0.10"},{"id":"c","text":"0.0875"},{"id":"d","text":"0.50"}],"correctOptionId":"a","explanation":"P(A or B) = P(A) + P(B) = 0.35 + 0.25 = 0.60.","difficulty":"Hard"},
  {"id":"SAT-10-04-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 4: Data Analysis and Probability","yearEC":"2024 E.C.","questionText":"Strong positive correlation between hours studied and scores. Which is NOT supported?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"More hours -> higher scores"},{"id":"b","text":"Studying causes higher scores with certainty"},{"id":"c","text":"Students who study more tend to score higher"},{"id":"d","text":"Linear relationship"}],"correctOptionId":"b","explanation":"Correlation does not imply causation.","difficulty":"Hard"}
"@

